fn box_constructor(rt:&mut Runtime,this:Value,value:Value)->JsResult<Value>{if !rt.is_construct_call(){return Ok(value)}let boxed=rt.to_object(value)?;let id=rt.object_id(boxed)?;let receiver=rt.object_id(this)?;rt.objects[id.0].prototype=rt.objects[receiver.0].prototype;Ok(boxed)}
fn number_constructor(rt:&mut Runtime,this:Value,args:&[Value],_:EnvId)->JsResult<Value>{let n=if args.is_empty(){0.0}else{rt.to_number(args[0])?};box_constructor(rt,this,Value::Number(n))}
fn string_constructor(rt:&mut Runtime,this:Value,args:&[Value],_:EnvId)->JsResult<Value>{let s=if args.is_empty(){rt.intern("")}else{rt.to_string(args[0])?};box_constructor(rt,this,Value::String(s))}
fn boolean_constructor(rt:&mut Runtime,this:Value,args:&[Value],_:EnvId)->JsResult<Value>{let v=Value::Bool(rt.truthy(arg(args,0)));box_constructor(rt,this,v)}
fn number_value_of(rt:&mut Runtime,this:Value,_:&[Value],_:EnvId)->JsResult<Value>{if let Value::Number(_)=this{return Ok(this)}if let Ok(id)=rt.object_id(this){if let ObjectKind::BoxedNumber(v)=rt.objects[id.0].kind{return Ok(Value::Number(v))}}Err(JsError::TypeError("Number receiver is not numeric".into()))}
fn number_string(rt:&mut Runtime,this:Value,args:&[Value],env:EnvId)->JsResult<Value>{let n=number_value_of(rt,this,&[],env)?;let radix=if matches!(arg(args,0),Value::Undefined){10.0}else{integer(rt,args[0])?};if !(2.0..=36.0).contains(&radix){return Err(JsError::RangeError("radix must be between 2 and 36".into()))}if radix!=10.0{let Value::Number(number)=n else{unreachable!()};if !number.is_finite(){return Ok(Value::String(rt.to_string(n)?))}let integer_domain=number.fract()==0.0&&((number.abs()<=9_007_199_254_740_991.0)||matches!(radix as u32,2|4|8|16|32)&&number.abs()<18_446_744_073_709_551_616.0);if !integer_domain{return Err(JsError::Unsupported("nondecimal fractional formatting is not implemented".into()))}let mut integer=number.abs()as u64;let mut digits=Vec::new();loop{let digit=(integer%(radix as u64))as u16;digits.push(if digit<10{48+digit}else{97+digit-10});integer/=radix as u64;if integer==0{break}}if number<0.0{digits.push(45)}digits.reverse();return Ok(rt.string_utf16(&digits))}Ok(Value::String(rt.to_string(n)?))}
fn string_value_of(rt:&mut Runtime,this:Value,_:&[Value],_:EnvId)->JsResult<Value>{if let Value::String(_)=this{return Ok(this)}if let Ok(id)=rt.object_id(this){if let ObjectKind::BoxedString(v)=rt.objects[id.0].kind{return Ok(Value::String(v))}}Err(JsError::TypeError("String receiver is not string".into()))}
fn boolean_value_of(rt:&mut Runtime,this:Value,_:&[Value],_:EnvId)->JsResult<Value>{if let Value::Bool(_)=this{return Ok(this)}if let Ok(id)=rt.object_id(this){if let ObjectKind::BoxedBoolean(v)=rt.objects[id.0].kind{return Ok(Value::Bool(v))}}Err(JsError::TypeError("Boolean receiver is not boolean".into()))}
fn boolean_string(rt:&mut Runtime,this:Value,_:&[Value],env:EnvId)->JsResult<Value>{let value=boolean_value_of(rt,this,&[],env)?;Ok(Value::String(rt.to_string(value)?))}

fn array_includes(rt:&mut Runtime,this:Value,args:&[Value],_:EnvId)->JsResult<Value>{let object=rt.to_object(this)?;let n=length(rt,object)?;if n==0{return Ok(Value::Bool(false))}let start=integer(rt,arg(args,1))?;if start>=n as f64{return Ok(Value::Bool(false))}for i in relative(start,n)..n{let value=get_index(rt,object,i)?;if rt.same_value_zero(value,arg(args,0)){return Ok(Value::Bool(true))}}Ok(Value::Bool(false))}
fn find_impl(rt:&mut Runtime,this:Value,args:&[Value],index:bool)->JsResult<Value>{let object=rt.to_object(this)?;let n=length(rt,object)?;let callback=arg(args,0);if !matches!(callback,Value::Function(_)){return Err(JsError::TypeError("array callback is not callable".into()))}for i in 0..n{let value=get_index(rt,object,i)?;let answer=rt.call_value(callback,arg(args,1),&[value,Value::Number(i as f64),object])?;if rt.truthy(answer){return Ok(if index{Value::Number(i as f64)}else{value})}}Ok(if index{Value::Number(-1.0)}else{Value::Undefined})}
fn array_find(rt:&mut Runtime,this:Value,args:&[Value],_:EnvId)->JsResult<Value>{find_impl(rt,this,args,false)}
fn array_find_index(rt:&mut Runtime,this:Value,args:&[Value],_:EnvId)->JsResult<Value>{find_impl(rt,this,args,true)}
fn reduce_impl(rt:&mut Runtime,this:Value,args:&[Value],right:bool)->JsResult<Value>{let object=rt.to_object(this)?;let n=length(rt,object)?;let callback=arg(args,0);if !matches!(callback,Value::Function(_)){return Err(JsError::TypeError("array callback is not callable".into()))}let indices=if right{(0..n).rev().collect::<Vec<_>>()}else{(0..n).collect::<Vec<_>>()};let mut accumulator=args.get(1).copied();for i in indices{if has_index(rt,object,i)?{let value=get_index(rt,object,i)?;accumulator=Some(if let Some(previous)=accumulator{rt.call_value(callback,Value::Undefined,&[previous,value,Value::Number(i as f64),object])?}else{value});}}accumulator.ok_or_else(||JsError::TypeError("Reduce of empty array with no initial value".into()))}
fn array_reduce(rt:&mut Runtime,this:Value,args:&[Value],_:EnvId)->JsResult<Value>{reduce_impl(rt,this,args,false)}
fn array_reduce_right(rt:&mut Runtime,this:Value,args:&[Value],_:EnvId)->JsResult<Value>{reduce_impl(rt,this,args,true)}
fn array_concat(rt:&mut Runtime,this:Value,args:&[Value],_:EnvId)->JsResult<Value>{let object=rt.to_object(this)?;let result=rt.array(&[]);let mut next=0;for item in std::iter::once(object).chain(args.iter().copied()){let spread=rt.object_id(item).is_ok_and(|id|matches!(rt.objects[id.0].kind,ObjectKind::Array{..}));if spread{let n=length(rt,item)?;for i in 0..n{if has_index(rt,item,i)?{let value=get_index(rt,item,i)?;let k=key(rt,next);rt.define_data(result,k,value,true,true,true)?;}next+=1;}}else{let k=key(rt,next);rt.define_data(result,k,item,true,true,true)?;next+=1;}}set_length(rt,result,next)?;Ok(result)}
